from html.parser import HTMLParser
from pathlib import Path
class Check(HTMLParser):
 def __init__(self):
  super().__init__(); self.links=[]; self.ids=[]; self.viewport=False
 def handle_starttag(self, tag, attrs):
  a=dict(attrs)
  if tag=='a': self.links.append(a.get('href'))
  if 'id' in a: self.ids.append(a['id'])
  if tag=='meta' and a.get('name')=='viewport': self.viewport='width=device-width' in a.get('content','')
s=Path('index.html').read_text(); c=Check(); c.feed(s)
assert c.links.count('#contact')==1, 'Expected one contact link'
assert c.ids.count('contact')==1, 'Contact destination missing or duplicated'
assert '>Get a quote</a>' in s, 'CTA label or link missing'
assert '<title>Example Garden Services</title>' in s, 'Business title changed'
assert c.viewport, 'Mobile viewport missing'
print('Agreed contact-navigation assertions passed; visual review still required')
